create perfetto table app as select upid from process where name='me.plei.pixelet';
create perfetto table win as select e-23000000000 a, e-3000000000 b from (select max(s.ts+s.dur) e from sched s join thread t using(utid) where t.upid in (select upid from app));
select 'SLICE' k, t.name thr, sl.name, count(*) n, round(sum(sl.dur)/1e9,2) total_s, round(avg(sl.dur)/1e6,1) avg_ms, round(max(sl.dur)/1e6,1) max_ms from slice sl join thread_track tt on sl.track_id=tt.id join thread t using(utid), win where t.upid in (select upid from app) and sl.ts>=win.a and sl.ts<win.b and (sl.name in ('QueuePresentKHR','postAndWait','dequeueBuffer','traversal') or sl.name like 'Choreographer#doFrame%') group by t.utid, case when sl.name like 'Choreographer%' then 'doFrame' else sl.name end order by total_s desc limit 14;
select 'LONG_MAIN' k, sl.name, round(sl.dur/1e6,1) ms from slice sl join thread_track tt on sl.track_id=tt.id join thread t using(utid), win where t.upid in (select upid from app) and t.name='me.plei.pixelet' and sl.name='postAndWait' and sl.ts>=win.a and sl.ts<win.b and sl.dur>50000000 order by sl.dur desc limit 12;
select 'LONG_MAIN_N' k, sum(sl.dur>16000000) over16, sum(sl.dur>50000000) over50, sum(sl.dur>100000000) over100, count(*) n from slice sl join thread_track tt on sl.track_id=tt.id join thread t using(utid), win where t.upid in (select upid from app) and t.name='me.plei.pixelet' and sl.name='postAndWait' and sl.ts>=win.a and sl.ts<win.b;
select 'STATE' k, t.name thr, ts.state, round(sum(ts.dur)/1e9,2) s from thread_state ts join thread t using(utid), win where t.upid in (select upid from app) and ts.ts>=win.a and ts.ts<win.b and t.name in ('xpute-gpu','xpute-core') group by t.utid, ts.state order by thr, s desc limit 12;
